{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "description": "Autopay mandate setup", // enter the description shown on the payment link here
  "currency": "INR",
  "amount": {{paylink_amount}}, // setup amount in paise (PENNY_DROP must be 200; TRANSATION >= 100)
  "expireAt": {{paylink_expire_at}}, // link expiry in epoch ms (auto-defaulted to now+24h)
  "constraints": [
    {
      "type": "ACCOUNT",
      "accountNumber": "{{account_number}}", // optional - restrict mandate to this bank account (TPV)
      "ifsc": "{{ifsc}}" // optional - allowed bank IFSC
    }
  ],
  "paymentFlow": {
    "type": "SUBSCRIPTION_PAYLINK_SETUP",
    "customerDetails": {
      "name": "{{customer_name}}", // enter the customer name here
      "phoneNumber": "{{customer_phone}}", // enter the customer mobile number here (link sent via SMS)
      "email": "{{customer_email}}" // enter the customer email here (link sent via EMAIL)
    },
    "notificationChannels": ["SMS", "EMAIL"], // channels used to deliver the payment link
    "subscriptionDetails": {
      "subscriptionType": "RECURRING",
      "merchantSubscriptionId": "{{merchant_subscription_id}}", // auto-generated each run (SUB_<timestamp>)
      "authWorkflowType": "{{auth_workflow_type}}", // TRANSACTION or PENNY_DROP
      "amountType": "FIXED", // FIXED or VARIABLE
      "maxAmount": {{max_amount}}, // max redemption amount in paise (max 1500000)
      "productType": "UPI_MANDATE",
      "frequency": "{{frequency}}", // DAILY / WEEKLY / MONTHLY / YEARLY / etc.
      "expireAt": {{subscription_expire_at}} // mandate validity in epoch ms (default 30 years)
    },
    "metaInfo": {
      "udf1": "udf1" // optional passthrough fields udf1-udf15
    }
  }
}

{
  "merchantOrderId": "{{redemption_order_id}}", // auto-generated each run (REDEEM_<timestamp>)
  "amount": {{redemption_amount}}, // amount to debit in paise (min 100, <= mandate maxAmount)
  "paymentFlow": {
    "type": "SUBSCRIPTION_CHECKOUT_REDEMPTION",
    "merchantSubscriptionId": "{{merchant_subscription_id}}", // the mandate to debit
    "redemptionRetryStrategy": "STANDARD", // STANDARD or CUSTOM
    "autoDebit": false // false = notify now and execute later (mandatory 24h gap); true = auto debit after gap
  }
}

{
  "merchantOrderId": "{{redemption_order_id}}" // the merchantOrderId used in Notify Redemption
}
